defmodule Orax.Integration.JsonTest do
  use ExUnit.Case, async: false

  @moduletag :oracle

  import Ecto.Query

  alias Orax.Integration
  alias Orax.Integration.Repo

  defmodule Doc do
    use Ecto.Schema

    schema "orax_it_json" do
      field :meta, :map
    end
  end

  setup_all do
    start_supervised!({Repo, Integration.config()})
    Integration.drop_table(Repo, "orax_it_json")

    Repo.query!(
      "CREATE TABLE orax_it_json (id INTEGER GENERATED BY DEFAULT AS IDENTITY " <>
        "PRIMARY KEY, meta JSON)"
    )

    Repo.query!(
      ~s|INSERT INTO orax_it_json (meta) VALUES (JSON('{"d":{"kind":"single","n":5,"ok":true},"tags":["x","y"]}'))|
    )

    Repo.query!(
      ~s|INSERT INTO orax_it_json (meta) VALUES (JSON('{"d":{"kind":"multi","n":"many","ok":false}}'))|
    )

    on_exit(fn ->
      Integration.with_repo(Repo, fn ->
        Integration.drop_table(Repo, "orax_it_json")
      end)
    end)

    :ok
  end

  defp count(query), do: Repo.aggregate(query, :count)

  test "filters on json paths" do
    assert count(where(Doc, [d], d.meta["d"]["kind"] == "single")) == 1
    assert count(where(Doc, [d], d.meta["d"]["kind"] == ^"multi")) == 1
    assert count(where(Doc, [d], d.meta["d"]["n"] > 4)) == 1
    assert count(where(Doc, [d], d.meta["d"]["ok"] == true)) == 1
    assert count(where(Doc, [d], d.meta["tags"][1] == "y")) == 1
    assert count(where(Doc, [d], is_nil(d.meta["tags"][0]))) == 1
  end

  test "selects json scalars" do
    assert Repo.all(from d in Doc, order_by: d.id, select: d.meta["d"]["kind"]) ==
             ["single", "multi"]
  end

  @tag skip: Integration.needs_ttc_23_4()
  test "json arrays come back as lists" do
    assert [%{"tags" => ["x", "y"]}, _] = Repo.all(from d in Doc, order_by: d.id, select: d.meta)

    assert %{rows: [[[1, 2, 3], ["a"], %{"l" => [true, nil]}]]} =
             Repo.query!(~s|SELECT JSON('[1,2,3]'), JSON('["a"]'), JSON('{"l":[true,null]}') FROM dual|)
  end
end
